package cz.recaption.core

/**
 * Texty přihlášení účtem PlayStation přes telefon: kroky průvodce v televizi (pa_…), stránka,
 * kterou televize vystaví telefonu (wp_…), a ReCaption v telefonu (hp_…).
 * LOGIN_S = čeština a slovenština, LOGIN_X = ostatní jazyky.
 */
internal val LOGIN_S: Map<String, Pair<String, String>> = mapOf(
    "pa_1_text" to ("PlayStation potřebuje vědět, ke kterému účtu se televize připojuje. Zjistí se to přihlášením k účtu PlayStation. Dělá se to v telefonu, jen jednou, a trvá to asi dvě minuty.\n\nV telefonu otevřít fotoaparát, namířit ho na čtvereček vlevo a klepnout na odkaz, který se objeví. Otevře se stránka ReCaption z této televize, proto musí být telefon na stejné Wi-Fi. Pak tady zvolit Pokračovat." to "PlayStation potrebuje vedieť, ku ktorému účtu sa televízor pripája. Zistí sa to prihlásením k účtu PlayStation. Robí sa to v telefóne, len raz, a trvá to asi dve minúty.\n\nV telefóne otvoriť fotoaparát, namieriť ho na štvorček vľavo a ťuknúť na odkaz, ktorý sa objaví. Otvorí sa stránka ReCaption z tohto televízora, preto musí byť telefón na rovnakej Wi-Fi. Potom tu zvoliť Pokračovať."),
    "pa_2_text" to ("1. V telefonu se přihlásit 🔵 účtem pro ReCaption (DRUHÝM účtem PlayStation), ne 🟢 herním účtem.\n2. Když se stránka zeptá na „passkey“, zvolit Remind Me Later.\n3. Zkopírovat adresu prázdné stránky „redirect“ a vložit ji na stránce ReCaption. Televize pak pokračuje sama." to "1. V telefóne sa prihlásiť 🔵 účtom pre ReCaption (DRUHÝM účtom PlayStation), nie 🟢 herným účtom.\n2. Keď sa stránka opýta na „passkey“, zvoliť Remind Me Later.\n3. Skopírovať adresu prázdnej stránky „redirect“ a vložiť ju na stránke ReCaption. Televízor potom pokračuje sám."),
    "pa_3_title" to ("Nejde to? Opsat kód ručně" to "Nejde to? Opísať kód ručne"),
    "pa_3_text" to ("Záloha, když se stránka z předchozího čtverečku v telefonu neotevře. Tenhle čtvereček vede rovnou na přihlášení Sony. Po přihlášení zůstane prázdná stránka „redirect“. Klepnout nahoře na její adresu a najít v ní „code=“. Sem se opíše to, co je hned za ním, až po znak & – přesně, i s tečkou a velkými písmeny. Kód platí jen pár minut." to "Záloha, keď sa stránka z predchádzajúceho štvorčeka v telefóne neotvorí. Tento štvorček vedie priamo na prihlásenie Sony. Po prihlásení zostane prázdna stránka „redirect“. Ťuknúť hore na jej adresu a nájsť v nej „code=“. Sem sa opíše to, čo je hneď za ním, až po znak & – presne, aj s bodkou a veľkými písmenami. Kód platí len pár minút."),
    "pa_stuck" to ("Stránka se neotevřela" to "Stránka sa neotvorila"),
    "pa_pc" to ("Nebo v počítači ve stejné síti otevřít v prohlížeči: " to "Alebo v počítači v rovnakej sieti otvoriť v prehliadači: "),
    "pa_nolan" to ("Stránku pro telefon se teď nepodařilo vystavit, čtvereček proto vede rovnou na přihlášení Sony. Po přihlášení se kód opíše ručně v dalším kroku." to "Stránku pre telefón sa teraz nepodarilo vystaviť, štvorček preto vedie priamo na prihlásenie Sony. Po prihlásení sa kód opíše ručne v ďalšom kroku."),
    "wp_web_h" to ("Přihlášení v prohlížeči" to "Prihlásenie v prehliadači"),
    "wp_1" to ("1. Klepnout na tlačítko. Přihlášení Sony se otevře na nové kartě." to "1. Ťuknúť na tlačidlo. Prihlásenie Sony sa otvorí na novej karte."),
    "wp_login_btn" to ("Přihlásit se u PlayStation" to "Prihlásiť sa u PlayStation"),
    "wp_2" to ("2. Přihlásit se 🔵 DRUHÝM účtem. Když se stránka zeptá na „passkey“, zvolit Remind Me Later. Nakonec zůstane skoro prázdná stránka se slovem „redirect“. Klepnout nahoře na její adresu a zvolit Kopírovat. Pak se v prohlížeči vrátit na tuto kartu ReCaption (není to aplikace) a adresu vložit níže. Když Sony heslo nechce a hned ukáže „redirect“, je v prohlížeči přihlášený jiný (třeba 🟢 herní) účet – adresu této stránky otevřít v anonymním okně a začít znovu." to "2. Prihlásiť sa 🔵 DRUHÝM účtom. Keď sa stránka opýta na „passkey“, zvoliť Remind Me Later. Nakoniec zostane takmer prázdna stránka so slovom „redirect“. Ťuknúť hore na jej adresu a zvoliť Kopírovať. Potom sa v prehliadači vrátiť na túto kartu ReCaption (nie je to aplikácia) a adresu vložiť nižšie. Keď Sony heslo nechce a hneď ukáže „redirect“, je v prehliadači prihlásený iný (napríklad 🟢 herný) účet – adresu tejto stránky otvoriť v anonymnom okne a začať znova."),
    "wp_3" to ("3. Zkopírovanou adresu vložit sem:" to "3. Skopírovanú adresu vložiť sem:"),
    "wp_send" to ("Odeslat do TV" to "Odoslať do TV"),
    "wp_ok" to ("Hotovo ✔ Účet je ověřený, pokračuje se na televizi." to "Hotovo ✔ Účet je overený, pokračuje sa na televízore."),
    "wp_bad" to ("Adresa neplatí nebo už vypršela (platí jen pár minut). Je potřeba se přihlásit znovu a vložit novou." to "Adresa neplatí alebo už vypršala (platí len pár minút). Treba sa prihlásiť znova a vložiť novú."),
    "wp_gone" to ("Televize už na tomto odkazu nečeká. Na ní je potřeba znovu otevřít krok se čtverečkem a naskenovat ho." to "Televízor už na tomto odkaze nečaká. Na ňom treba znova otvoriť krok so štvorčekom a naskenovať ho."),
    "wp_easy_h" to ("Nejjednodušší: ReCaption v telefonu (bez kopírování)" to "Najjednoduchšie: ReCaption v telefóne (bez kopírovania)"),
    "wp_app_inst" to ("Když aplikace v telefonu ještě není, tlačítko ji stáhne. Po instalaci se vrátit na tuto stránku a klepnout na tlačítko znovu." to "Keď aplikácia v telefóne ešte nie je, tlačidlo ju stiahne. Po inštalácii sa vrátiť na túto stránku a ťuknúť na tlačidlo znova."),
    "wp_app_text" to ("Aplikace v telefonu (jen Android) se přihlásí sama, nic se nekopíruje a účet si zapamatuje pro příště." to "Aplikácia v telefóne (len Android) sa prihlási sama, nič sa nekopíruje a účet si zapamätá nabudúce."),
    "wp_app_btn" to ("Otevřít v aplikaci ReCaption" to "Otvoriť v aplikácii ReCaption"),
    "wp_app_get" to ("Stáhnout ReCaption do telefonu" to "Stiahnuť ReCaption do telefónu"),
    "hp_title" to ("Přihlášení pro TV" to "Prihlásenie pre TV"),
    "hp_intro" to ("Tady se přihlašuje účtem PlayStation a telefon ho pošle do televize. Účet si zapamatuje, takže příště stačí jedno klepnutí. Heslo se zadává přímo na stránce Sony; aplikace si ukládá jen číslo účtu." to "Tu sa prihlasuje účtom PlayStation a telefón ho pošle do televízora. Účet si zapamätá, takže nabudúce stačí jedno ťuknutie. Heslo sa zadáva priamo na stránke Sony; aplikácia si ukladá len číslo účtu."),
    "hp_scan" to ("Na televizi otevřít v ReCaptionu krok se čtverečkem, naskenovat ho fotoaparátem telefonu a na stránce zvolit „Otevřít v aplikaci ReCaption“." to "Na televízore otvoriť v ReCaptione krok so štvorčekom, naskenovať ho fotoaparátom telefónu a na stránke zvoliť „Otvoriť v aplikácii ReCaption“."),
    "hp_tv_ready" to ("TV čeká na účet ✔" to "TV čaká na účet ✔"),
    "hp_login_top" to ("Přihlásit se 🔵 DRUHÝM účtem PlayStation (ne 🟢 tím, na kterém se hraje). Když se stránka zeptá na „passkey“, zvolit Remind Me Later." to "Prihlásiť sa 🔵 DRUHÝM účtom PlayStation (nie 🟢 tým, na ktorom sa hrá). Keď sa stránka opýta na „passkey“, zvoliť Remind Me Later."),
    "hp_saved" to ("Uložené účty" to "Uložené účty"),
    "hp_forget" to ("Zapomenout" to "Zabudnúť"),
    "hp_sent" to ("Hotovo ✔ Účet je v televizi, pokračuje se tam." to "Hotovo ✔ Účet je v televízore, pokračuje sa tam."),
    "hp_send_fail" to ("Televize neodpovídá. Telefon musí být na stejné Wi-Fi jako televize a na televizi musí být otevřený krok se čtverečkem. Čtvereček je potřeba naskenovat znovu." to "Televízor neodpovedá. Telefón musí byť na rovnakej Wi-Fi ako televízor a na televízore musí byť otvorený krok so štvorčekom. Štvorček treba naskenovať znova."),
    "hp_browser" to ("Nejde to? Přihlásit se v prohlížeči" to "Nejde to? Prihlásiť sa v prehliadači"),
    "hp_browser_text" to ("Přihlásit se v prohlížeči. Na skoro prázdné stránce se slovem „redirect“ zvolit Sdílet a vybrat ReCaption." to "Prihlásiť sa v prehliadači. Na takmer prázdnej stránke so slovom „redirect“ zvoliť Zdieľať a vybrať ReCaption."),
    "hp_is_tv" to ("Tohle je TV nebo box" to "Toto je TV alebo box"),
    "hp_read_btn" to ("Číst pro TV" to "Čítať pre TV"),
    "hp_back" to ("Pomocník pro přihlášení" to "Pomocník na prihlásenie"),
    "hp_back_app" to ("Zpět do aplikace" to "Späť do aplikácie"),
    "hp_acc" to ("Účet PlayStation" to "Účet PlayStation"),
)

